{"code": "import pandas as pd
df = pd.read_csv('data.csv')
df['date'] = pd.to_datetime(df['date'], format='%m/%d/%y')
d = df[df.account_id=='YxSxqn0'].copy()

def deltas(d1, d2):
    out={}
    for col in ['csp','cloud_service','application','instance_family']:
        a = d[d.date==d1].groupby(col).unblended_cost.sum()
        b = d[d.date==d2].groupby(col).unblended_cost.sum()
        c = pd.DataFrame({'a':a,'b':b}).fillna(0)
        c['delta']=c.a-c.b
        out[col]=c[c.delta.abs()>40]
    return out

for (x,y) in [('2025-10-13','2025-10-08'),('2025-10-13','2025-10-11'),('2025-10-11','2025-10-08')]:
    print(x,y)
    for col,t in deltas(pd.Timestamp(x),pd.Timestamp(y)).items():
        print(col); print(t.to_string())
    print('---')
